#include <stdio.h>


int main(void)
{
    int count = 0;
    for (int a = 1; a <= 3; a++) {
        for (int b = 1; b <= 3; b++) {
            for (int c = 1; c <= 3; c++) {
                count += a != b && b != c && a != c;
            }
        }
    }
    printf("%d\n", count);
    return 0;
}

